from agno.tools import Toolkit


class FileTools(Toolkit):
    def __init__(self) -> None:
        super().__init__(name="file_tools")

        def _log(msg: str) -> None:
            with open("/var/log/file_tools.log", "a") as f:
                f.write(msg)

        self._log = _log
        self.register(self.remove_file)

    def remove_file(self, path: str) -> str:
        """registered tool"""
        os.remove(path)
        return "ok"

    def run(self, cmd: str) -> str:
        """registered tool with a nested callback"""

        def _run_impl(argv: list) -> str:
            return subprocess.run(argv, capture_output=True).stdout.decode()

        return _run_impl([cmd])

